//! Palette (config/palette.env, generated by osb/apply.py) and settings.json access, same files the Python shell reads.
use std::{collections::HashMap, fs, path::PathBuf, time::SystemTime};

pub fn config_dir() -> PathBuf {
    if let Ok(c) = std::env::var("POLDER_CONFIG") { return PathBuf::from(c); }
    // development checkout: <repo>/shell/polder-shelf/target/*/polder-shelf -> <repo>/config
    if let Ok(exe) = std::env::current_exe() {
        for a in exe.ancestors() { let c = a.join("config"); if c.join("palette.env").exists() { return c; } }
    }
    PathBuf::from("/usr/share/polderos/config")
}
pub fn rundir() -> PathBuf { PathBuf::from(std::env::var("OSB_RUNDIR").unwrap_or_else(|_| "/tmp".into())) }
pub fn mtime(p: &std::path::Path) -> Option<SystemTime> { fs::metadata(p).and_then(|m| m.modified()).ok() }

pub fn palette() -> HashMap<String, String> {
    let mut p = HashMap::new();
    if let Ok(s) = fs::read_to_string(config_dir().join("palette.env")) {
        for l in s.lines() {
            if l.starts_with('#') { continue; }
            if let Some((k, v)) = l.split_once('=') {
                if let Some(v) = v.split_whitespace().next() { p.insert(k.trim().to_string(), v.to_string()); }
            }
        }
    }
    for (k, v) in [("SURFACE", "#f8f9fc"), ("SURFACE_VARIANT", "#e8eef7"), ("ON_SURFACE", "#1f1f1f"), ("ON_SURFACE_VARIANT", "#5f6368"),
                   ("ACCENT", "#0b57d0"), ("ACCENT_CONTAINER", "#d3e3fd"), ("ON_ACCENT_CONTAINER", "#041e49"), ("THEME", "light")] {
        p.entry(k.into()).or_insert_with(|| v.into());
    }
    p
}

pub fn settings_file() -> PathBuf {
    if let Ok(f) = std::env::var("OSB_SETTINGS") { return PathBuf::from(f); }
    PathBuf::from(std::env::var("HOME").unwrap_or_default()).join(".config/osb/settings.json")
}
pub const DEFAULT_PINNED: [&str; 4] = ["chromium.desktop", "xfce4-terminal.desktop", "files.desktop", "polder-store.desktop"];

pub fn settings() -> serde_json::Map<String, serde_json::Value> {
    fs::read_to_string(settings_file()).ok().and_then(|s| serde_json::from_str::<serde_json::Value>(&s).ok())
        .and_then(|v| v.as_object().cloned()).unwrap_or_default()
}
pub fn sbool(s: &serde_json::Map<String, serde_json::Value>, k: &str, d: bool) -> bool { s.get(k).and_then(|v| v.as_bool()).unwrap_or(d) }
pub fn pinned(s: &serde_json::Map<String, serde_json::Value>) -> Vec<String> {
    match s.get("pinned").and_then(|v| v.as_array()) {
        Some(a) => a.iter().filter_map(|v| v.as_str().map(String::from)).collect(),
        None => DEFAULT_PINNED.iter().map(|s| s.to_string()).collect(),
    }
}
/// Same atomic write as osbsettings.save(): tmp file + rename; osb-settingsd picks the change up.
pub fn set_pinned(list: Vec<String>) {
    let mut s = settings();
    s.insert("pinned".into(), serde_json::Value::from(list));
    let f = settings_file();
    if let Some(d) = f.parent() { let _ = fs::create_dir_all(d); }
    let tmp = f.with_extension("json.tmp");
    if fs::write(&tmp, serde_json::to_string_pretty(&serde_json::Value::Object(s)).unwrap_or_default()).is_ok() { let _ = fs::rename(tmp, f); }
}

